import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createFileStore, DEFAULT_TEXT } from '../store.js'

function withTempDir(fn) {
  const dir = mkdtempSync(join(tmpdir(), 'hello-'))
  try {
    return fn(dir)
  } finally {
    rmSync(dir, { recursive: true, force: true })
  }
}

test('DEFAULT_TEXT is "hello world"', () => {
  assert.equal(DEFAULT_TEXT, 'hello world')
})

test('read() returns the default text when no file exists', () => {
  withTempDir((dir) => {
    const store = createFileStore(join(dir, 'hello.json'))
    assert.equal(store.read(), 'hello world')
  })
})

test('write() then a new store instance reads the persisted text', () => {
  withTempDir((dir) => {
    const file = join(dir, 'hello.json')
    createFileStore(file).write('bonjour')
    assert.equal(createFileStore(file).read(), 'bonjour')
  })
})

test('unicode and newlines round-trip byte-for-byte', () => {
  withTempDir((dir) => {
    const file = join(dir, 'hello.json')
    const text = 'héllo 🌍\nline2'
    createFileStore(file).write(text)
    assert.equal(createFileStore(file).read(), text)
  })
})

test('write() creates missing parent directories', () => {
  withTempDir((dir) => {
    const file = join(dir, 'data', 'nested', 'x.json')
    const store = createFileStore(file)
    store.write('deep')
    assert.equal(store.read(), 'deep')
  })
})

test('read() propagates a real IO error instead of returning the default', () => {
  withTempDir((dir) => {
    const blocker = join(dir, 'blocker')
    writeFileSync(blocker, 'not a directory')
    const store = createFileStore(join(blocker, 'hello.json'))
    assert.throws(() => store.read())
  })
})

test('write() rejects non-string input with a TypeError', () => {
  withTempDir((dir) => {
    const store = createFileStore(join(dir, 'hello.json'))
    assert.throws(() => store.write(42), TypeError)
    assert.equal(store.read(), 'hello world')
  })
})

test('mkdirSync failures during write propagate', () => {
  withTempDir((dir) => {
    const blocker = join(dir, 'blocker')
    writeFileSync(blocker, 'not a directory')
    const store = createFileStore(join(blocker, 'hello.json'))
    assert.throws(() => store.write('x'))
  })
