  background-image: linear-gradient(100deg, #ffffff, #b7c3ff 35%, #7dd3fc 70%, #f0abfc);
  background-size: 220% 100%;
  background-position: 0% 50%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  filter: drop-shadow(0 0 40px rgba(125, 211, 252, 0.35));
  animation: shimmer 12s ease-in-out infinite alternate;
  outline-offset: 0.2em;
  border-radius: 0.1em;
}

#text::selection {
  background: rgba(125, 211, 252, 0.35);
  -webkit-text-fill-color: #f8fbff;
}

#text:focus {
  outline: 2px solid rgba(125, 211, 252, 0.55);
  outline-offset: 0.15em;
}

#text:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 0.2em;
  border-radius: 0.1em;
}

@keyframes shimmer {
  from {
    background-position: 0% 50%;
  }
  to {
    background-position: 100% 50%;
  }
}

#text.saved {
  animation:
    shimmer 12s ease-in-out infinite alternate,
    brighten 1.2s ease;
}

@keyframes brighten {
  0%,
  100% {
    filter: drop-shadow(0 0 40px rgba(125, 211, 252, 0.35));
  }
  40% {
    filter: brightness(1.25) drop-shadow(0 0 60px rgba(125, 211, 252, 0.6));
  }
}

/* ---- status pill ---- */

.status {
  position: fixed;
  bottom: clamp(1rem, 5vh, 3rem);
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
  padding: 0.5em 1.1em;
  border: 1px solid rgba(219, 227, 255, 0.22);
  border-radius: 999px;
  background: rgba(6, 8, 20, 0.72);
  color: var(--text-soft);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0.75;
  transition: opacity 0.3s ease;
}

.status::before {
  content: "";
  width: 0.55em;
  height: 0.55em;
  border-radius: 50%;
  background: #8b96c4;
}

.status.saving,
.status.saved,
.status.error {
  opacity: 1;
}

.status.saving::before {
  background: #fcd34d;
}

.status.saved::before {
  background: #34d399;
}

.status.error::before {
  background: #f87171;
}

.status.saved {
  animation: pulse 1.2s ease;
}

@keyframes pulse {
  0%,
  100% {
    transform: translateX(-50%) scale(1);
  }
  45% {
    transform: translateX(-50%) scale(1.07);
  }
}

noscript p {
  margin-top: 2rem;
  font-size: 0.9rem;
  letter-spacing: 0.08em;
}

/* ---- responsive ---- */

@media (max-width: 640px) {
  .blob {
    filter: blur(50px);
  }
}

/* ---- reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }
}

import { chromium } from '/home/ian/.local/share/mise/installs/npm-playwright/1.63.0/node_modules/playwright/index.js'
import { spawn } from 'node:child_process'
import { mkdtempSync, rmSync, readFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { mkdirSync } from 'node:fs'

const REPO = '/home/ian/hello-world'
const PORT = 3100
const BASE = `http://127.0.0.1:${PORT}`
const SHOTS = '/tmp/hello-shots'

const work = mkdtempSync(join(tmpdir(), 'hello-e2e-'))
const dataFile = join(work, 'data', 'hello.json')
mkdirSync(SHOTS, { recursive: true })

const consoleMessages = []
const pageErrors = []
const failures = []

function check(name, detail) {
  console.log(`PASS  ${name}${detail ? ` — ${detail}` : ''}`)
}

function fail(name, detail) {
  failures.push(`${name}: ${detail}`)
  console.log(`FAIL  ${name} — ${detail}`)
}

function assert(condition, name, detail) {
  if (condition) check(name, detail)
  else fail(name, detail)
}

async function waitFor(fn, timeout, label) {
  const deadline = Date.now() + timeout
  for (;;) {
    let value
    try {
      value = await fn()
    } catch {
      value = undefined
    }
    if (value) return value
    if (Date.now() > deadline) throw new Error(`timed out after ${timeout}ms waiting for ${label}`)
    await new Promise((r) => setTimeout(r, 50))
  }
}

function startServer() {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ['main.js'], {
      cwd: REPO,
      env: { ...process.env, PORT: String(PORT), DATA_FILE: dataFile },
    })
    let out = ''
    let err = ''
    child.stdout.on('data', (d) => {
      out += d
      console.log(`  [server] ${d.toString().trimEnd()}`)
      if (out.includes('Editing at')) resolve(child)
    })
    child.stderr.on('data', (d) => {
      err += d
      console.log(`  [server stderr] ${d.toString().trimEnd()}`)
    })
    child.on('error', reject)
    setTimeout(() => reject(new Error(`server did not start; stdout=${out} stderr=${err}`)), 5000)
  })
}

function stopServer(child) {
  return new Promise((resolve) => {
    child.on('exit', resolve)
    child.kill()
  })
}

function instrument(page) {
  page.on('console', (msg) => {
    consoleMessages.push(`[${msg.type()}] ${msg.text()}`)
  })
  page.on('pageerror', (error) => {
    pageErrors.push(String(error))
  })
}

let server = await startServer()
const browser = await chromium.launch()

try {
  // 1: fresh page shows the default greeting
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page = await context.newPage()
  instrument(page)
  await page.goto(BASE, { waitUntil: 'networkidle' })
  const initial = await page.textContent('#text')
  assert(initial === 'hello world', 'E2E-1 default greeting', JSON.stringify(initial))

  // 9a: idle desktop screenshot + no horizontal scroll
  await page.screenshot({ path: join(SHOTS, 'desktop-1440.png') })
  const desktopScroll = await page.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
  }))
  assert(
    desktopScroll.scrollWidth <= desktopScroll.clientWidth,
    'E2E-9 no horizontal scroll @1440',
    `scrollWidth=${desktopScroll.scrollWidth} clientWidth=${desktopScroll.clientWidth}`,
  )

  // 3: click, select all, type
  await page.click('#text')
  await page.keyboard.press('Control+A')
  await page.keyboard.type('hey you')
  const focusShot = page.screenshot({ path: join(SHOTS, 'desktop-focus.png') })
  const statusText = await waitFor(
    () => page.textContent('#status').then((t) => (t.includes('Saved') ? t : undefined)),
    2000,
    'status pill to read Saved',
  )
  await focusShot
  check('E2E-3 typed text is saved', `status=${JSON.stringify(statusText)}`)

  // 4: the data file on disk contains the new text
  const onDisk = readFileSync(dataFile, 'utf8')
  assert(onDisk === 'hey you', 'E2E-4 data file on disk', JSON.stringify(onDisk))

  // 5: survives reload
  await page.reload({ waitUntil: 'networkidle' })
  const afterReload = await page.textContent('#text')
  assert(afterReload === 'hey you', 'E2E-5 survives reload', JSON.stringify(afterReload))
  await context.close()

  // 6: survives a server restart
  await stopServer(server)
  server = await startServer()
  const context2 = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page2 = await context2.newPage()
  instrument(page2)
  await page2.goto(BASE, { waitUntil: 'networkidle' })
  const afterRestart = await page2.textContent('#text')
  assert(afterRestart === 'hey you', 'E2E-6 survives server restart', JSON.stringify(afterRestart))
  await context2.close()

  // 7: survives a fresh browser profile (new context)
  const context3 = await browser.newContext({ viewport: { width: 390, height: 844 } })
  const page3 = await context3.newPage()
  instrument(page3)
  await page3.goto(BASE, { waitUntil: 'networkidle' })
  const freshProfile = await page3.textContent('#text')
  assert(freshProfile === 'hey you', 'E2E-7 fresh browser context', JSON.stringify(freshProfile))

  // 9b: mobile screenshot + no horizontal scroll
  await page3.screenshot({ path: join(SHOTS, 'mobile-390.png') })
  const mobileScroll = await page3.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
  }))
  assert(
    mobileScroll.scrollWidth <= mobileScroll.clientWidth,
    'E2E-9 no horizontal scroll @390',
    `scrollWidth=${mobileScroll.scrollWidth} clientWidth=${mobileScroll.clientWidth}`,
  )
  await context3.close()

  // 10: reduced motion disables animations
  const context4 = await browser.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: 'reduce' })
  const page4 = await context4.newPage()
  instrument(page4)
  await page4.goto(BASE, { waitUntil: 'networkidle' })
  const blobAnimation = await page4.evaluate(() => getComputedStyle(document.querySelector('.blob')).animationName)
  assert(blobAnimation === 'none', 'E2E-10 reduced motion disables blob animation', `animation-name=${blobAnimation}`)
  const textAnimation = await page4.evaluate(() => getComputedStyle(document.querySelector('#text')).animationName)
  assert(textAnimation === 'none', 'E2E-10 reduced motion disables headline animation', `animation-name=${textAnimation}`)
  await page4.screenshot({ path: join(SHOTS, 'desktop-reduced-motion.png') })
  await context4.close()

  // 8: keyboard-only path — Tab reaches #text and typing changes it
  const context5 = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page5 = await context5.newPage()
  instrument(page5)
  await page5.goto('about:blank')
  await page5.goto(BASE, { waitUntil: 'networkidle' })
  await page5.keyboard.press('Tab')
  const focusedId = await page5.evaluate(() => document.activeElement?.id)
  assert(focusedId === 'text', 'E2E-8 Tab focuses the headline', `activeElement id=${JSON.stringify(focusedId)}`)
  await page5.keyboard.press('End')
  await page5.keyboard.type('!')
  const typed = await page5.textContent('#text')
  assert(typed === 'hey you!', 'E2E-8 keyboard typing edits the greeting', JSON.stringify(typed))
  await page5.keyboard.press('Escape')
  await context5.close()

  // 11: stored content is rendered as text, never as HTML
  const context6 = await browser.newContext({ viewport: { width: 1440, height: 900 } })
  const page6 = await context6.newPage()
  instrument(page6)
  const dialogs = []
  page6.on('dialog', async (dialog) => {
    dialogs.push(dialog.message())
    await dialog.dismiss()
  })
  await page6.goto(BASE, { waitUntil: 'networkidle' })
  const payload = '<img src=x onerror=alert(1)>'
  await page6.click('#text')
  await page6.keyboard.press('Control+A')
  await page6.keyboard.type(payload)
  const rendered = await page6.textContent('#text')
  const imgCount = await page6.locator('#text img').count()
  assert(rendered === payload, 'E2E-11 markup is displayed literally', JSON.stringify(rendered))
  assert(imgCount === 0, 'E2E-11 no injected img element', `img count=${imgCount}`)
  await page6.waitForTimeout(600)
  assert(dialogs.length === 0, 'E2E-11 no dialog (no script execution)', JSON.stringify(dialogs))
  await context6.close()
} finally {
  await browser.close()
  await stopServer(server)
}

// 2: console / page error hygiene
const noisy = consoleMessages.filter((m) => m.startsWith('[error]') || m.startsWith('[warning]'))
assert(noisy.length === 0, 'E2E-2 no console errors or warnings', noisy.length ? noisy.join(' | ') : 'console log empty')
assert(pageErrors.length === 0, 'E2E-2 no page errors', pageErrors.length ? pageErrors.join(' | ') : 'no page errors')
console.log(`  console messages captured: ${JSON.stringify(consoleMessages, null, 0)}`)
console.log(`  page errors captured: ${JSON.stringify(pageErrors, null, 0)}`)

console.log(`\n${failures.length === 0 ? 'E2E PASS' : `E2E FAIL (${failures.length})`}`)
for (const f of failures) console.log(` - ${f}`)
console.log(`screenshots in ${SHOTS}`)
rmSync(work, { recursive: true, force: true })
process.exit(failures.length === 0 ? 0 : 1)

